-- Ejecutar una vez en SQL Editor de Supabase. Es seguro repetirlo: no reinicia existencias.
begin;
create table if not exists public.prisma_members(user_id uuid primary key references auth.users(id) on delete cascade);
create table if not exists public.prisma_products(id bigint generated by default as identity primary key,code text not null unique,name text not null,kind text not null,provider text not null,category text not null default 'tinta',minimum numeric not null default 1000,maximum numeric not null default 0,shelf_days integer not null default 365,cost_kg numeric not null default 0,container_grams numeric not null default 4000);
create table if not exists public.prisma_lots(id bigint generated by default as identity primary key,product_id bigint not null references public.prisma_products(id),lot text not null,entry_date date not null,shelf_days integer not null,cost_kg numeric not null,grams numeric not null,unique(product_id,lot));
create table if not exists public.prisma_orders(id bigint generated by default as identity primary key,folio text not null,client text not null,date date not null,notes text not null default '',status text not null default 'confirmed',pressman text not null default '',product text not null default '');
create table if not exists public.prisma_items(id bigint generated by default as identity primary key,order_id bigint not null references public.prisma_orders(id),lot_id bigint not null references public.prisma_lots(id),np text not null default '',initial_grams numeric,final_grams numeric,grams numeric not null,cost_kg numeric not null,meters numeric,notes text not null default '');
create table if not exists public.prisma_movements(id bigint generated by default as identity primary key,lot_id bigint not null references public.prisma_lots(id),type text not null check(type in ('initial','in','out')),grams numeric not null,cost_kg numeric not null,date date not null,reason text not null,order_id bigint references public.prisma_orders(id));
create table if not exists public.prisma_cuts(id bigint generated by default as identity primary key,month text not null unique,created_at timestamptz not null default now(),snapshot jsonb not null);
create table if not exists public.prisma_metadata(key text primary key,value text not null);
-- No hay lectura o escritura pública, ni acceso directo de usuarios a las tablas.
alter table public.prisma_members enable row level security;
alter table public.prisma_products enable row level security;
alter table public.prisma_lots enable row level security;
alter table public.prisma_orders enable row level security;
alter table public.prisma_items enable row level security;
alter table public.prisma_movements enable row level security;
alter table public.prisma_cuts enable row level security;
alter table public.prisma_metadata enable row level security;
revoke all on public.prisma_members, public.prisma_products, public.prisma_lots, public.prisma_orders, public.prisma_items, public.prisma_movements, public.prisma_cuts, public.prisma_metadata from anon, authenticated;

create or replace function public.prisma_today() returns date language sql stable set search_path=public,pg_temp as $$ select timezone('America/Mexico_City',now())::date $$;
create or replace function public.prisma_authorize() returns void language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if auth.uid() is null or not exists(select 1 from public.prisma_members where user_id=auth.uid()) then raise exception 'Tu cuenta no tiene acceso a este inventario.'; end if;
end $$;
create or replace function public.prisma_date(v text) returns date language plpgsql set search_path=public,pg_temp as $$
declare d date;
begin
 if v is null or v !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Fecha no válida.'; end if;
 d:=v::date;
 if d>public.prisma_today() then raise exception 'No se permiten fechas futuras.'; end if;
 if d<(select value::date from public.prisma_metadata where key='baseline') then raise exception 'La fecha es anterior a la carga inicial.'; end if;
 if exists(select 1 from public.prisma_cuts where month>=to_char(d,'YYYY-MM')) then raise exception 'El período está cerrado.'; end if;
 return d;
end $$;
create or replace function public.prisma_number(v text, label text, minimum numeric default 0) returns numeric language plpgsql set search_path=public,pg_temp as $$
declare n numeric;
begin
 if v is null or btrim(v)='' then raise exception '%: falta una cantidad.',label; end if;
 n:=v::numeric;
 if n::text in ('NaN','Infinity','-Infinity') or n<minimum or n>1000000000000 then raise exception '%: cantidad no válida.',label; end if;
 return n;
end $$;
create or replace function public.prisma_product(b jsonb) returns bigint language plpgsql set search_path=public,pg_temp as $$
declare c text;pid bigint;
begin
 c:=upper(btrim(b->>'code'));if c='UIAPP50EP021ID' then c:='APP50EP021ID';end if;
 if c is null or c='' then raise exception 'Falta el código.';end if;
 select id into pid from public.prisma_products where code=c;if found then return pid;end if;
 if coalesce(btrim(b->>'name'),'')='' or coalesce(btrim(b->>'kind'),'')='' or coalesce(btrim(b->>'provider'),'')='' then raise exception 'Faltan nombre, tipo o proveedor.';end if;
 insert into public.prisma_products(code,name,kind,provider,category,minimum) values(c,b->>'name',b->>'kind',b->>'provider',case when b->>'category'='herramental' then 'herramental' else 'tinta' end,public.prisma_number(coalesce(b->>'minimum','1000'),'Mínimo')) returning id into pid;
 return pid;
end $$;

create table if not exists public.prisma_preparations(id bigint generated by default as identity primary key,date date not null,folio text not null,np text not null,start_time text not null,end_time text not null,end_next_day boolean not null default false,minutes numeric not null,requested_date date,requested_time text,supplies text not null,product text not null,notes text not null default '');
alter table public.prisma_preparations enable row level security;
revoke all on public.prisma_preparations from anon,authenticated;
create or replace function public.prisma_save_preparation(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
<<prep>>
declare b jsonb:=payload;d date;requested date;initial_time text;final_time text;requested_time text;next_day boolean;duration numeric;record_id bigint;
begin
 perform public.prisma_authorize();perform pg_advisory_xact_lock(104202611);
 if coalesce(b->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Fecha no válida.';end if;
 d:=(b->>'date')::date;if d>public.prisma_today() then raise exception 'No se permiten preparaciones con fecha futura.';end if;
 initial_time:=b->>'start_time';final_time:=b->>'end_time';requested_time:=nullif(b->>'requested_time','');
 if coalesce(initial_time,'') !~ '^([01]\d|2[0-3]):[0-5]\d(:[0-5]\d)?$' or coalesce(final_time,'') !~ '^([01]\d|2[0-3]):[0-5]\d(:[0-5]\d)?$' then raise exception 'Horas de inicio o fin no válidas.';end if;
 if requested_time is not null and requested_time !~ '^([01]\d|2[0-3]):[0-5]\d(:[0-5]\d)?$' then raise exception 'Hora solicitada no válida.';end if;
 next_day:=coalesce((b->>'end_next_day')::boolean,false);
 duration:=extract(epoch from (final_time::time-initial_time::time))+(case when next_day then 86400 else 0 end);
 if duration<0 then raise exception 'La hora de fin es anterior al inicio. Indica si terminó al día siguiente.';end if;
 if duration>86400 then raise exception 'La preparación no puede superar 24 horas.';end if;
 duration:=round(duration/60,2);
 if nullif(b->>'requested_date','') is not null and b->>'requested_date' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Fecha solicitada no válida.';end if;
 requested:=nullif(b->>'requested_date','')::date;
 if coalesce(btrim(b->>'folio'),'')='' or coalesce(btrim(b->>'np'),'')='' or coalesce(btrim(b->>'supplies'),'')='' or coalesce(btrim(b->>'product'),'')='' then raise exception 'Faltan orden, NP, insumos o producto.';end if;
 record_id:=nullif(b->>'id','')::bigint;
 if record_id is null then
  insert into public.prisma_preparations(date,folio,np,start_time,end_time,end_next_day,minutes,requested_date,requested_time,supplies,product,notes) values(d,b->>'folio',b->>'np',initial_time,final_time,next_day,duration,requested,requested_time,b->>'supplies',b->>'product',coalesce(b->>'notes','')) returning id into record_id;
 else
  update public.prisma_preparations set date=d,folio=b->>'folio',np=b->>'np',start_time=initial_time,end_time=final_time,end_next_day=next_day,minutes=duration,requested_date=requested,requested_time=prep.requested_time,supplies=b->>'supplies',product=b->>'product',notes=coalesce(b->>'notes','') where id=record_id;
  if not found then raise exception 'Registro de preparación no encontrado.';end if;
 end if;
 return jsonb_build_object('ok',true,'id',record_id);
end $$;
revoke all on function public.prisma_save_preparation(jsonb) from public,anon,authenticated;
grant execute on function public.prisma_save_preparation(jsonb) to authenticated;

create or replace function public.prisma_state() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
 perform public.prisma_authorize();
 return jsonb_build_object('today',public.prisma_today(),'baseline',(select value from public.prisma_metadata where key='baseline'),
 'preparations',coalesce((select jsonb_agg(to_jsonb(r) order by r.date desc,r.start_time desc,r.id desc) from public.prisma_preparations r),'[]'::jsonb),
 'products',coalesce((select jsonb_agg(to_jsonb(p) order by name) from public.prisma_products p),'[]'::jsonb),
 'lots',coalesce((select jsonb_agg(to_jsonb(x) order by x.name,x.entry_date) from (select l.*,p.name,p.code,p.kind,p.provider,p.category,p.minimum,p.maximum,p.container_grams from public.prisma_lots l join public.prisma_products p on p.id=l.product_id)x),'[]'::jsonb),
 'movements',coalesce((select jsonb_agg(to_jsonb(x) order by x.date desc,x.id desc) from (select m.*,p.name,p.code,l.lot from public.prisma_movements m join public.prisma_lots l on l.id=m.lot_id join public.prisma_products p on p.id=l.product_id)x),'[]'::jsonb),
 'orders',coalesce((select jsonb_agg(to_jsonb(o)||jsonb_build_object('lines',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from (select i.*,p.name,p.code,l.lot from public.prisma_items i join public.prisma_lots l on l.id=i.lot_id join public.prisma_products p on p.id=l.product_id where i.order_id=o.id)x),'[]'::jsonb)) order by o.date desc,o.id desc) from public.prisma_orders o),'[]'::jsonb),
 'cuts',coalesce((select jsonb_agg(to_jsonb(c) order by month desc) from public.prisma_cuts c),'[]'::jsonb));
end $$;

create or replace function public.prisma_action(operation text,payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
<<rpc>>
declare b jsonb:=payload;d date;pid bigint;lid bigint;oid bigint;l public.prisma_lots%rowtype;o public.prisma_orders%rowtype;p public.prisma_products%rowtype;i jsonb;m record;amount numeric;initial numeric;final numeric;consumed numeric;meters numeric;folio text;np text;draft boolean;weighing boolean;status text;mon text;snapshot jsonb;reason text;
begin
 perform public.prisma_authorize();
 -- Serialize balance-changing operations across clients, within the PostgreSQL transaction.
 perform pg_advisory_xact_lock(104202611);
 if operation='products' then perform public.prisma_product(b);
 elsif operation='movements' then
  d:=public.prisma_date(b->>'date');amount:=public.prisma_number(b->>'grams','Cantidad',0.001);reason:=btrim(b->>'reason');
  if reason is null or reason='' then raise exception 'Falta el motivo.';end if;
  if b->>'type' not in ('in','out') or b->>'type' is null then raise exception 'Tipo no válido.';end if;
  if nullif(b->>'lot_id','') is not null then lid:=(b->>'lot_id')::bigint;
  elsif b->>'type'='in' then
   pid:=coalesce(nullif(b->>'product_id','')::bigint,public.prisma_product(b));select * into p from public.prisma_products where id=pid;
   if not found then raise exception 'Producto no encontrado.';end if;
   if coalesce(btrim(b->>'lot'),'')='' then raise exception 'Falta el lote.';end if;
   select id into lid from public.prisma_lots where product_id=pid and lot=b->>'lot';
   if not found then insert into public.prisma_lots(product_id,lot,entry_date,shelf_days,cost_kg,grams) values(pid,b->>'lot',d,public.prisma_number(coalesce(b->>'shelf_days',p.shelf_days::text),'Caducidad')::integer,public.prisma_number(coalesce(b->>'cost_kg',p.cost_kg::text),'Costo'),0) returning id into lid;end if;
  end if;
  select * into l from public.prisma_lots where id=lid;if not found then raise exception 'Lote no encontrado.';end if;
  if b->>'type'='out' and l.grams<amount then raise exception 'Existencia insuficiente.';end if;
  update public.prisma_lots set grams=grams+case when b->>'type'='in' then amount else -amount end where id=lid;
  insert into public.prisma_movements(lot_id,type,grams,cost_kg,date,reason) values(lid,b->>'type',amount,l.cost_kg,d,reason);
 elsif operation in ('orders','orders/update') then
  oid:=null;
  if operation='orders/update' then oid:=(b->>'id')::bigint;select * into o from public.prisma_orders where id=oid;if not found or o.status<>'draft' then raise exception 'Solo puedes editar registros pendientes.';end if;perform public.prisma_date(o.date::text);end if;
  d:=public.prisma_date(b->>'date');folio:=btrim(b->>'folio');weighing:=coalesce(b->>'capture_mode'='weighing',false);draft:=weighing and coalesce(b->>'status'='draft',false);status:=case when draft then 'draft' else 'confirmed' end;
  if coalesce(folio,'')='' then raise exception 'Falta la orden.';end if;
  if weighing and (coalesce(btrim(b->>'product'),'')='' or coalesce(btrim(b->>'pressman'),'')='') then raise exception 'Falta producto o prensista.';end if;
  if not weighing and coalesce(btrim(b->>'client'),'')='' then raise exception 'Falta el cliente.';end if;
  if not weighing and exists(select 1 from public.prisma_orders where prisma_orders.folio=rpc.folio and prisma_orders.status<>'cancelled' and id<>coalesce(oid,0)) then raise exception 'Ya existe esa orden.';end if;
  if jsonb_typeof(b->'lines') is distinct from 'array' or jsonb_array_length(b->'lines')=0 then raise exception 'Agrega al menos una tinta.';end if;
  if oid is null then insert into public.prisma_orders(folio,client,date,notes,status,pressman,product) values(folio,coalesce(nullif(b->>'client',''),b->>'product',''),d,coalesce(b->>'notes',''),status,coalesce(b->>'pressman',''),coalesce(b->>'product','')) returning id into oid;
  else update public.prisma_orders set folio=rpc.folio,client=coalesce(nullif(b->>'client',''),b->>'product',''),date=d,notes=coalesce(b->>'notes',''),status=rpc.status,pressman=coalesce(b->>'pressman',''),product=coalesce(b->>'product','') where id=oid;delete from public.prisma_items where order_id=oid;end if;
  for i in select value from jsonb_array_elements(b->'lines') loop
   lid:=(i->>'lot_id')::bigint;select pl.* into l from public.prisma_lots pl join public.prisma_products pp on pp.id=pl.product_id where pl.id=lid and pp.category='tinta';if not found then raise exception 'Selecciona un lote de tinta.';end if;
   np:=coalesce(btrim(i->>'np'),'');initial:=null;final:=null;
   if weighing then
    if np='' then raise exception 'Falta el NP.';end if;
    if exists(select 1 from public.prisma_orders po join public.prisma_items pi on pi.order_id=po.id where po.id<>oid and po.folio=rpc.folio and po.date=d and po.status<>'cancelled' and pi.np=rpc.np) then raise exception 'Ya hay un registro de esta orden, fecha y NP.';end if;
    initial:=public.prisma_number(i->>'initial_grams','Peso inicial');if nullif(i->>'final_grams','') is not null then final:=public.prisma_number(i->>'final_grams','Peso final');end if;
    if final is null and not draft then raise exception 'Falta el peso final.';end if;
    if final>initial then raise exception 'El peso final no puede superar al inicial.';end if;
    consumed:=coalesce(round(initial-final,3),0);
   else consumed:=public.prisma_number(i->>'grams','Gramos',0.001);end if;
   meters:=null;if nullif(i->>'meters','') is not null then meters:=public.prisma_number(i->>'meters','Metros');end if;
   insert into public.prisma_items(order_id,lot_id,np,initial_grams,final_grams,grams,cost_kg,meters,notes) values(oid,lid,np,initial,final,consumed,l.cost_kg,meters,coalesce(i->>'notes',''));
  end loop;
  if not draft then for m in select lot_id,sum(grams) as amount,max(cost_kg) as cost from public.prisma_items where order_id=oid group by lot_id loop
   if m.amount>0 then
    select * into l from public.prisma_lots where id=m.lot_id;if l.grams<m.amount then raise exception 'Existencia insuficiente en el lote %.',l.lot;end if;
    update public.prisma_lots set grams=grams-m.amount where id=m.lot_id;
    insert into public.prisma_movements(lot_id,type,grams,cost_kg,date,reason,order_id) values(m.lot_id,'out',m.amount,m.cost,d,'Orden '||folio,oid);
   end if;
  end loop;end if;
 elsif operation='orders/cancel' then
  select * into o from public.prisma_orders where id=(b->>'id')::bigint;if not found or o.status='cancelled' then raise exception 'Registro no encontrado o ya cancelado.';end if;
  perform public.prisma_date(o.date::text);d:=public.prisma_date(public.prisma_today()::text);
  for m in select * from public.prisma_movements where order_id=o.id and type='out' loop
   update public.prisma_lots set grams=grams+m.grams where id=m.lot_id;
   insert into public.prisma_movements(lot_id,type,grams,cost_kg,date,reason,order_id) values(m.lot_id,'in',m.grams,m.cost_kg,d,'Cancelación '||o.folio,o.id);
  end loop;
  update public.prisma_orders set status='cancelled' where id=o.id;
 elsif operation='cuts' then
  mon:=b->>'month';if mon is null or mon !~ '^\d{4}-(0[1-9]|1[0-2])$' then raise exception 'Mes no válido.';end if;
  if mon>=to_char(public.prisma_today(),'YYYY-MM') then raise exception 'El mes todavía no termina.';end if;
  if mon<(select substr(value,1,7) from public.prisma_metadata where key='baseline') then raise exception 'No hay historia para ese mes.';end if;
  if exists(select 1 from public.prisma_cuts where month=mon) then raise exception 'Ese mes ya está cerrado.';end if;
  if exists(select 1 from public.prisma_orders po where po.status='draft' and to_char(po.date,'YYYY-MM')<=mon) then raise exception 'Completa o cancela los registros pendientes.';end if;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into snapshot from (
   select pl.id as lot_id,pp.name,pp.code,pl.lot,pp.category,pl.cost_kg,
   coalesce(sum(case when to_char(pm.date,'YYYY-MM')<mon or (to_char(pm.date,'YYYY-MM')=mon and pm.type='initial') then case when pm.type='out' then -pm.grams else pm.grams end else 0 end),0) as opening,
   coalesce(sum(case when to_char(pm.date,'YYYY-MM')=mon and pm.type='in' then pm.grams else 0 end),0) as incoming,
   coalesce(sum(case when to_char(pm.date,'YYYY-MM')=mon and pm.type='out' then pm.grams else 0 end),0) as outgoing,
   coalesce(sum(case when to_char(pm.date,'YYYY-MM')<=mon then case when pm.type='out' then -pm.grams else pm.grams end else 0 end),0) as closing
   from public.prisma_lots pl join public.prisma_products pp on pp.id=pl.product_id left join public.prisma_movements pm on pm.lot_id=pl.id group by pl.id,pp.id
  )x;
  insert into public.prisma_cuts(month,snapshot) values(mon,snapshot);
 else raise exception 'Operación no válida.';
 end if;
 return jsonb_build_object('ok',true);
end $$;
-- Helpers are never callable through the public API; only these two authenticated RPCs are exposed.
revoke all on function public.prisma_today(),public.prisma_authorize(),public.prisma_date(text),public.prisma_number(text,text,numeric),public.prisma_product(jsonb),public.prisma_state(),public.prisma_action(text,jsonb) from public,anon,authenticated;
grant execute on function public.prisma_state(),public.prisma_action(text,jsonb) to authenticated;

-- Carga inicial única: repetir el archivo no duplica lotes ni reinicia saldos.
do $seed$
declare item jsonb; pid bigint;lid bigint;
begin
